package com.baisylia.culturaldelights.legacy;
import cpw.mods.fml.common.*;
import cpw.mods.fml.common.eventhandler.SubscribeEvent;
import cpw.mods.fml.common.gameevent.TickEvent;
import java.util.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import net.minecraft.world.WorldServer;
import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.server.MinecraftServer;
import net.minecraft.init.*;
import net.minecraft.item.*;
import net.minecraft.block.Block;
import net.minecraft.inventory.*;
import net.minecraft.nbt.NBTTagCompound;
import com.google.gson.*;
import vectorwing.farmersdelight.legacy.*;
public final class Checks {
    private int ticks;private boolean done;private final List<String> report=new ArrayList<String>();private WorldServer w;private EntityPlayerMP player;
    static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
    public Checks(){if(FMLCommonHandler.instance().getSide().isClient()&&Catalog.MOD.equals("croptopia"))try{Class.forName("com.baisylia.culturaldelights.legacy.client.ClientChecks").getMethod("init").invoke(null);}catch(Exception e){throw new RuntimeException(e);}}
    @SubscribeEvent public void tick(TickEvent.ServerTickEvent e){if(done||e.phase!=TickEvent.Phase.END||++ticks<30)return;done=true;
        try{w=MinecraftServer.getServer().worldServerForDimension(0);player=new Cook(w);player.setPosition(0,81,0);if("restart".equals(System.getProperty("foodports.phase")))reload();else run();report.add("Failed: 0");}catch(Throwable t){t.printStackTrace();report.add("FAIL: "+t);report.add("Failed: 1");}
        try{Files.write(Paths.get("checks-"+Catalog.MOD+"-"+System.getProperty("foodports.phase","initial")+".txt"),report,StandardCharsets.UTF_8);}catch(Exception x){throw new RuntimeException(x);}
        if(FMLCommonHandler.instance().getSide().isServer())MinecraftServer.getServer().initiateShutdown();
    }
    private static final class Cook extends net.minecraftforge.common.util.FakePlayer {Cook(WorldServer w){super(w,new com.mojang.authlib.GameProfile(UUID.fromString("00000000-0000-0000-0000-00000000f00d"),"GardenChecks"));playerNetServerHandler=new net.minecraft.network.NetHandlerPlayServer(MinecraftServer.getServer(),new net.minecraft.network.NetworkManager(false),this){public void sendPacket(net.minecraft.network.Packet packet){}};}public void addStat(net.minecraft.stats.StatBase stat,int n){if(stat!=null)func_147099_x().func_150873_a(this,stat,func_147099_x().writeStat(stat)+n);}}
    private void pass(String text){report.add("PASS: "+text);}
    private void run(){
        check(Port.CONTENT.items.size()==Port.CONTENT.data.getAsJsonObject("items").entrySet().size(),"Registry count differs from original inventory");
        for(Map.Entry<String,Item> e:Port.CONTENT.items.entrySet())check(Item.itemRegistry.getObject(Catalog.MOD+":"+e.getKey())==e.getValue(),"Registry identity "+e.getKey());pass("All "+Port.CONTENT.items.size()+" original item identities are registered without collisions");
        int foodCount=0;for(Map.Entry<String,Item> e:Port.CONTENT.items.entrySet())if(e.getValue() instanceof Food){Food food=(Food)e.getValue();for(int i=0;i<36;i++)player.inventory.setInventorySlotContents(i,null);NBTTagCompound foodState=new NBTTagCompound();player.getFoodStats().writeNBT(foodState);foodState.setInteger("foodLevel",0);foodState.setFloat("foodSaturationLevel",0);player.getFoodStats().readNBT(foodState);ItemStack s=new ItemStack(food,2);ItemStack out=food.onEaten(s,w,player);check(player.getFoodStats().getFoodLevel()==Math.min(20,Catalog.num(food.definition,"hunger",0)),"Food value "+e.getKey());boolean infinite=Catalog.yes(food.definition,"infinite");check(out.stackSize==(infinite?2:1)&&out.getItem()==food,"Food consumption count "+e.getKey());String rest=Catalog.str(food.definition,"returnItem","");if(!rest.isEmpty()){ItemStack expected=Port.CONTENT.stack(rest);boolean found=false;for(int slot=0;slot<36;slot++)found|=Stacks.same(expected,player.inventory.getStackInSlot(slot));check(found,"Stacked food lost container "+e.getKey());ItemStack last=food.onEaten(new ItemStack(food),w,player);check(Stacks.same(last,expected),"Final food lost container "+e.getKey());}for(JsonElement fx:food.definition.getAsJsonArray("effects")){JsonObject effect=fx.getAsJsonObject();net.minecraft.potion.Potion potion=Food.potion(Catalog.str(effect,"name",""));if(potion!=null&&effect.get("chance").getAsFloat()==1){net.minecraft.potion.PotionEffect active=player.getActivePotionEffect(potion);check(active!=null&&active.getAmplifier()==Catalog.num(effect,"level",0)&&active.getDuration()==Catalog.num(effect,"duration",0),"Source food effect "+e.getKey());}}check(food.getItemUseAction(out)==(Catalog.yes(food.definition,"drink")?EnumAction.drink:EnumAction.eat),"Source food animation "+e.getKey());player.clearActivePotions();foodCount++;}check(foodCount>25,"Too few edible foods");pass("All "+foodCount+" native foods use source hunger values and consume or return their source containers correctly");
        int cropCount=0;int base=Catalog.MOD.equals("croptopia")?0:80;
        for(Plant p:Port.CONTENT.crops.values())if(!p.upper){int x=base+cropCount*2;w.setBlock(x,79,0,Blocks.farmland,7,3);w.setBlockToAir(x,80,0);Seeds seed=(Seeds)Port.CONTENT.items.get(p.seed);ItemStack stack=new ItemStack(seed,2);check(seed.onItemUse(stack,player,w,x,79,0,1,.5F,1,.5F),"Seed planting "+p.id);check(w.getBlock(x,80,0)==p&&stack.stackSize==1,"Seed placement count "+p.id);for(int i=0;i<20;i++)p.func_149853_b(w,w.rand,x,80,0);check((w.getBlockMetadata(x,80,0)&7)==p.maxAge,"Bonemeal growth "+p.id);ArrayList<ItemStack> immature=Loot.drops(p.id,0,0,null,new Random(42));if(Catalog.MOD.equals("culturaldelights"))check(!immature.isEmpty(),"Immature crop lost its source seed "+p.id);else check(immature.isEmpty(),"Immature Croptopia crop must retain the original empty drop "+p.id);if(Catalog.MOD.equals("croptopia")){check(p.onBlockActivated(w,x,80,0,player,1,.5F,.5F,.5F),"Right click harvest "+p.id);check(w.getBlockMetadata(x,80,0)==0,"Harvest did not reset "+p.id);}cropCount++;}
        pass("All "+cropCount+" crops plant through native item use, consume one seed, grow with bonemeal and preserve native harvest behavior");
        for(JsonElement tree:Port.CONTENT.data.getAsJsonArray("trees")){JsonObject t=tree.getAsJsonObject();String id=Catalog.str(t,"leaves","");GardenBlock leaves=Port.CONTENT.blocks.get(id);if(Catalog.yes(t,"wood"))continue;int x=base;w.setBlock(x,80,5,leaves,leaves.maxAge,3);check(leaves.onBlockActivated(w,x,80,5,player,1,.5F,.5F,.5F),"Fruit harvest "+id);check(w.getBlockMetadata(x,80,5)==0,"Fruit age reset "+id);check(!Loot.drops(id,leaves.maxAge,0,new ItemStack(Items.shears),new Random(1)).isEmpty(),"Sheared fruit leaves "+id);w.setBlockToAir(x,80,5);}pass("Original fruit-leaf families harvest and reset age without removing the tree; shearing preserves block drops");
        int grown=0;for(JsonObject def:Port.CONTENT.trees){int X=400+grown*10;for(int dx=-3;dx<=3;dx++)for(int dz=-3;dz<=3;dz++)w.setBlock(X+dx,79,dz,Blocks.grass);check(Gardens.tree(w,new Random(42+grown),X,80,0,def),"Tree failed to grow "+Catalog.str(def,"id",""));boolean fruit=false;Block expected=Port.CONTENT.blocks.get(Catalog.str(def,"leaves",""));for(int dx=-3;dx<=3;dx++)for(int dz=-3;dz<=3;dz++)for(int dy=80;dy<100;dy++)fruit|=w.getBlock(X+dx,dy,dz)==expected;check(fruit,"Tree generated no original fruit leaves "+Catalog.str(def,"id",""));grown++;}pass("All "+grown+" source tree families generate a native trunk and the correct fruit-leaf identity");
        int crafted=0;for(SourceCrafting r:SourceCrafting.ALL)if(r.id.startsWith(Catalog.MOD+":")){InventoryCrafting grid=new InventoryCrafting(new Container(){public boolean canInteractWith(net.minecraft.entity.player.EntityPlayer p){return true;}},3,3);List<List<ItemStack>> in=r.grid();for(int i=0;i<in.size();i++)if(in.get(i)!=null&&!in.get(i).isEmpty())grid.setInventorySlotContents(i,in.get(i).get(0).copy());check(r.matches(grid,w),"Native recipe does not match "+r.id);ItemStack out=r.getCraftingResult(grid);check(Stacks.same(out,r.output)&&out.stackSize==r.output.stackSize,"Craft output mismatch "+r.id);crafted++;}check(crafted>15,"Too few registered recipes: "+crafted);pass("All "+crafted+" available original crafting recipes match a real native grid and return the exact output count");
        int utensil=0;for(Item item:Port.CONTENT.items.values())if(item instanceof Ingredient&&item.hasContainerItem(new ItemStack(item))){ItemStack s=new ItemStack(item);check(item.getContainerItem(s).getItem()==item&&item.getContainerItem(s)!=s,"Utensil remainder aliases consumed stack");utensil++;}pass("Reusable utensils return independent one-item crafting remainders ("+utensil+" checked)");
        if(Catalog.MOD.equals("culturaldelights")){boolean poached=false;int cooked=0;for(CookingRecipes.Recipe recipe:CookingRecipes.ALL)if(recipe.id.startsWith(Catalog.MOD+":")){poached|=recipe.output.getItem()==Port.CONTENT.items.get("poached_eggplants");w.setBlock(base+5,79,8,Blocks.lava);w.setBlock(base+5,80,8,Content.cookingPot);CookingPotTile pot=(CookingPotTile)w.getTileEntity(base+5,80,8);for(int i=0;i<recipe.inputs.size();i++)pot.setInventorySlotContents(i,recipe.inputs.get(i).get(0).copy());for(int i=0;i<=recipe.time;i++)pot.updateEntity();ItemStack cookedOutput=Stacks.empty(pot.getStackInSlot(6))?pot.getStackInSlot(8):pot.getStackInSlot(6);check(Stacks.same(cookedOutput,recipe.output)&&cookedOutput.stackSize==recipe.output.stackSize,"Native pot failed "+recipe.id);cooked++;w.setBlockToAir(base+5,80,8);}check(poached,"Poached eggplant pot recipe missing");pass("All "+cooked+" available source pot recipes cook through a real heated native tile");int cutting=0;for(CuttingRecipes.Recipe r:CuttingRecipes.ALL)if(r.id.startsWith(Catalog.MOD+":")){w.setBlock(base+7,79,8,Blocks.stone);w.setBlock(base+7,80,8,Content.cuttingBoard);CuttingBoardTile board=(CuttingBoardTile)w.getTileEntity(base+7,80,8);ItemStack tool=new ItemStack(r.tool.equals("knife")?Content.ITEMS.get("iron_knife"):r.tool.equals("shears")?Items.shears:Items.iron_axe);board.setInventorySlotContents(0,r.inputs.get(0).copy());check(board.process(tool,null),"Native board failed "+r.id);check(Stacks.empty(board.getStackInSlot(0)),"Board retained input "+r.id);cutting++;w.setBlockToAir(base+7,80,8);}check(cutting>5,"Cutting recipes missing");pass("Cooking-pot and cutting-board recipe families are present in the native Farmer's Delight catalogs");
            GardenBlock feast=Port.CONTENT.blocks.get("eggplant_parmesan_block");w.setBlock(base,79,8,Blocks.stone);w.setBlock(base,80,8,feast,0,3);GardenTile tile=(GardenTile)w.getTileEntity(base,80,8);check(tile.remaining==4,"Initial serving count");player.inventory.setInventorySlotContents(0,new ItemStack(Items.bowl,4));player.inventory.currentItem=0;for(int i=0;i<4;i++)check(feast.onBlockActivated(w,base,80,8,player,1,.5F,.5F,.5F),"Serving failed");check(tile.remaining==0,"Feast serving count");NBTTagCompound n=new NBTTagCompound();tile.writeToNBT(n);GardenTile clone=new GardenTile();clone.readFromNBT(n);check(clone.remaining==0,"Feast NBT");pass("Four native bowl servings consume containers once and preserve the empty feast through NBT");}
        else{ItemStack fallback=new ItemStack(Items.fish);int changed=0;Random rolls=new Random(42);for(int i=0;i<10000;i++)if(HarvestEvents.fish(fallback,rolls)!=fallback)changed++;check(changed>2500&&changed<4500,"Fishing replacement probability "+changed);pass("Original fishing table replacement produces weighted source seafood and retains ordinary catches");}
        Plant first=Port.CONTENT.crops.values().iterator().next();w.setBlock(base,79,12,Blocks.farmland,7,3);w.setBlock(base,80,12,first,first.maxAge,3);pass("A real mature crop is saved for a second-JVM reload check");
    }
    private void reload(){int x=Catalog.MOD.equals("croptopia")?0:80;Plant first=Port.CONTENT.crops.values().iterator().next();check(w.getBlock(x,80,12)==first&&w.getBlockMetadata(x,80,12)==first.maxAge,"Saved crop identity or age was lost");pass("A fresh server reload preserves source crop identity and mature metadata");if(Catalog.MOD.equals("culturaldelights")){GardenTile tile=(GardenTile)w.getTileEntity(x,80,8);check(tile!=null&&tile.remaining==0,"Saved feast was lost");pass("A fresh server reload preserves the empty feast and its servings");}}
}
